import UIKit

/**
 * [EN] Slides the new page in from one edge while the old page leaves at the other, for a `UITabBarControllerDelegate`
 *      transition. Translated from Objective-C (docs/Swift-Migration.md); Objective-C callers get this class from
 *      `CYLSwiftInterface.h`.
 * [CN] 用于 `UITabBarControllerDelegate` 转场：新页面从一侧滑入，旧页面从另一侧滑出。已从 Objective-C 翻译
 *      （docs/Swift-Migration.md）；Objective-C 调用方通过 `CYLSwiftInterface.h` 使用本类。
 */
@objc(CYLTabBarSlideTransitionAnimator)
public class CYLTabBarSlideTransitionAnimator: NSObject, UIViewControllerAnimatedTransitioning {

    /**
     * [EN] The edge the old page leaves toward (`.right`: the new page comes from the left).
     * [CN] 旧页面滑出的方向（`.right`：新页面从左侧进入）。
     */
    @objc public let targetEdge: UIRectEdge

    /**
     * [EN] The animation length, 0.35 s by default.
     * [CN] 动画时长，默认 0.35 秒。
     */
    @objc public var duration: TimeInterval = 0.35

    /**
     * [EN] An animator for `targetEdge`.
     * [CN] 针对 `targetEdge` 的动画器。
     */
    @objc(initWithTargetEdge:)
    public init(targetEdge: UIRectEdge) {
        self.targetEdge = targetEdge
        super.init()
    }

    @available(*, unavailable)
    override public init() {
        fatalError("Use init(targetEdge:)")
    }

    public func transitionDuration(using _: UIViewControllerContextTransitioning?) -> TimeInterval {
        duration
    }

    public func animateTransition(using transitionContext: UIViewControllerContextTransitioning) {
        guard let fromViewController = transitionContext.viewController(forKey: .from),
              let toViewController = transitionContext.viewController(forKey: .to) else {
            transitionContext.completeTransition(!transitionContext.transitionWasCancelled)
            return
        }
        let fromView: UIView = transitionContext.view(forKey: .from) ?? fromViewController.view
        let toView: UIView = transitionContext.view(forKey: .to) ?? toViewController.view
        let fromFrame = transitionContext.initialFrame(for: fromViewController)
        let toFrame = transitionContext.finalFrame(for: toViewController)
        let offset: CGFloat = targetEdge == .right ? 1 : -1
        fromView.frame = fromFrame
        toView.frame = toFrame.offsetBy(dx: -toFrame.width * offset, dy: 0)
        transitionContext.containerView.addSubview(toView)
        UIView.animate(withDuration: transitionDuration(using: transitionContext), animations: {
            fromView.frame = fromFrame.offsetBy(dx: fromFrame.width * offset, dy: 0)
            toView.frame = toFrame
        }, completion: { _ in
            let cancelled = transitionContext.transitionWasCancelled
            if cancelled {
                fromView.frame = fromFrame
            }
            transitionContext.completeTransition(!cancelled)
        })
    }
}

/**
 * [EN] Drives a tab transition with a pan gesture: it finishes past 40 % of the width and cancels when the pan turns
 *      back. Translated from Objective-C (docs/Swift-Migration.md); Objective-C callers get this class from
 *      `CYLSwiftInterface.h`.
 * [CN] 用拖动手势驱动 Tab 转场：超过宽度的 40% 即完成，拖动反向时取消。已从 Objective-C 翻译（docs/Swift-Migration.md）；
 *      Objective-C 调用方通过 `CYLSwiftInterface.h` 使用本类。
 */
@objc(CYLTabBarInteractiveTransition)
public class CYLTabBarInteractiveTransition: UIPercentDrivenInteractiveTransition {

    /**
     * [EN] The pan gesture that drives the transition.
     * [CN] 驱动转场的拖动手势。
     */
    @objc public let gestureRecognizer: UIPanGestureRecognizer

    private weak var transitionContext: UIViewControllerContextTransitioning?
    private var initialTranslation: CGPoint = .zero

    /**
     * [EN] A transition driven by `gestureRecognizer`.
     * [CN] 由 `gestureRecognizer` 驱动的转场。
     */
    @objc(initWithGestureRecognizer:)
    public init(gestureRecognizer: UIPanGestureRecognizer) {
        self.gestureRecognizer = gestureRecognizer
        super.init()
        gestureRecognizer.addTarget(self, action: #selector(gestureRecognizerDidUpdate(_:)))
    }

    @available(*, unavailable)
    override public init() {
        fatalError("Use init(gestureRecognizer:)")
    }

    deinit {
        gestureRecognizer.removeTarget(self, action: #selector(gestureRecognizerDidUpdate(_:)))
    }

    override public func startInteractiveTransition(_ transitionContext: UIViewControllerContextTransitioning) {
        self.transitionContext = transitionContext
        initialTranslation = gestureRecognizer.translation(in: transitionContext.containerView)
        super.startInteractiveTransition(transitionContext)
    }

    /**
     * [EN] The progress of the pan, or -1 when it turned back.
     * [CN] 拖动的进度；拖动反向时为 -1。
     */
    private func percent(for gestureRecognizer: UIPanGestureRecognizer) -> CGFloat {
        guard let containerView = transitionContext?.containerView, containerView.bounds.width > 0 else {
            return 0
        }
        let translation = gestureRecognizer.translation(in: containerView)
        if (translation.x > 0 && initialTranslation.x < 0) || (translation.x < 0 && initialTranslation.x > 0) {
            return -1
        }
        return abs(translation.x) / containerView.bounds.width
    }

    @objc private func gestureRecognizerDidUpdate(_ gestureRecognizer: UIPanGestureRecognizer) {
        let percent = percent(for: gestureRecognizer)
        switch gestureRecognizer.state {
        case .began:
            break
        case .changed:
            if percent < 0 {
                cancel()
                gestureRecognizer.removeTarget(self, action: #selector(gestureRecognizerDidUpdate(_:)))
            } else {
                update(percent)
            }
        case .ended:
            if percent >= 0.4 {
                finish()
            } else {
                cancel()
            }
        default:
            cancel()
        }
    }
}
